const listing = $('List Subscribers').all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]);
const shaByName = Object.fromEntries(listing.map(f => [f.name, f.sha]));
const out = [];
const now = Date.now();
const WEEK = 7 * 24 * 60 * 60 * 1000;
for (const item of $('Fetch Subscriber File').all()) {
  const sub = item.json;
  if (sub.status !== 'active') continue;
  const isBaseline = !sub.last_scanned;
  const due = isBaseline || (now - Date.parse(sub.last_scanned)) >= WEEK;
  if (!due) continue;
  const stop = new Set(['the','a','an','llc','inc','co','company','of','and']);
  const words = String(sub.business_name).toLowerCase().replace(/[^a-z0-9 ]/g, '').split(/\s+/).filter(w => w && !stop.has(w));
  out.push({ json: { ...sub, isBaseline, searchTerm: words[0] || sub.business_name.toLowerCase(), gh_sha: shaByName[sub.id + '.json'] } });
}
return out;

