const resp = $input.item.json;
if (resp.stop_reason === 'refusal') throw new Error('Model declined');
const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('').replace(/^```json\n?|```$/g, '').trim();
const verdict = JSON.parse(text);
const sub = $('Filter Due Subscribers').item.json;
const updated = {
  id: sub.id, email: sub.email, business_name: sub.business_name, industry: sub.industry,
  stripe_customer: sub.stripe_customer, stripe_session: sub.stripe_session, status: sub.status,
  created_at: sub.created_at,
  last_scanned: new Date().toISOString(),
  known_marks_snapshot: verdict.new_snapshot || sub.known_marks_snapshot
};
return [{ json: { verdict, subscriber: updated, gh_sha: sub.gh_sha } }];
